      const emailValid = fields.email.validate(fields.email.input.value);
      const phoneValid = fields.phone.validate(fields.phone.input.value);

      setFieldState(fields.fullName, fullNameValid);
      setFieldState(fields.email, emailValid);
      setFieldState(fields.phone, phoneValid);

      return [
        { field: fields.fullName, valid: fullNameValid },
        { field: fields.email, valid: emailValid },
        { field: fields.phone, valid: phoneValid }
      ];
    }

