      event.preventDefault();

      const results = validateForm();
      const firstInvalid = results.find(({ valid }) => !valid);

      if (firstInvalid) {
        status.hidden = true;
        firstInvalid.field.input.focus();
        return;
      }

      status.textContent = 'Thanks — your message has been prepared for submission.';
      status.hidden = false;
      form.reset();
      Object.values(fields).forEach((field) => setFieldState(field, true));
      fields.fullName.input.focus();
    });

