             aria-describedby="phone-number-help phone-number-error">
           <p class="help-text" id="phone-number-help">Format: +1 555 123 4567 or (555) 123-4567.</p>
           <p class="error-text" id="phone-number-error" hidden>Please enter a phone number in the expected format.</p>
         </div>

         <div class="form-actions">
