   <script>
     const form = document.getElementById('support-form');
     const status = document.getElementById('form-status');
     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         validate(value) {
           return value.trim().length > 0;
         }
       },
       email: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         validate(value) {
           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
         }
       },
       phone: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) return true;
           return /^\+?\d[\d\s()-]{7,}$/.test(trimmed);
         }
       }
     };

     function setFieldState(field, isValid) {
       field.input.setAttribute('aria-invalid', String(!isValid));
       field.error.hidden = isValid;
     }

     function validateForm() {
       const fullNameValid = fields.fullName.validate(fields.fullName.input.value);
       const emailValid = fields.email.validate(fields.email.input.value);
       const phoneValid = fields.phone.validate(fields.phone.input.value);

       setFieldState(fields.fullName, fullNameValid);
       setFieldState(fields.email, emailValid);
       setFieldState(fields.phone, phoneValid);

       return [
         { field: fields.fullName, valid: fullNameValid },
         { field: fields.email, valid: emailValid },
         { field: fields.phone, valid: phoneValid }
       ];
     }

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const results = validateForm();
       const firstInvalid = results.find(({ valid }) => !valid);

       if (firstInvalid) {
         status.hidden = true;
         firstInvalid.field.input.focus();
         return;
       }

       status.textContent = 'Thanks — your message has been prepared for submission.';
       status.hidden = false;
       form.reset();
       Object.values(fields).forEach((field) => setFieldState(field, true));
       fields.fullName.input.focus();
     });

     ['input', 'blur'].forEach((eventName) => {
       Object.values(fields).forEach((field) => {
         field.input.addEventListener(eventName, () => {
           const isValid = field.validate(field.input.value);
           if (eventName === 'blur' || field.input.value.trim() !== '') {
             setFieldState(field, isValid);
           } else {
             field.input.removeAttribute('aria-invalid');
             field.error.hidden = true;
           }
')

